"""Build conservative simplified-only sampling data from pinned OpenCC mappings."""
import hashlib,json,pathlib
ROOT=pathlib.Path(__file__).resolve().parent.parent
file=ROOT/'data/reference-sources/opencc/STCharacters.txt'
rows=[line.split('\t') for line in file.read_text().splitlines() if line and not line.startswith('#')]
traditional={c for _,values in rows for c in values.split()}
moe=set(json.loads((ROOT/'data/moe-common-4808.json').read_text())['characters'])
chars=''.join(sorted({key for key,_ in rows if len(key)==1 and key not in traditional and key not in moe}))
(ROOT/'script-preferences.js').write_text('// Generated by scripts/build-script-preferences.py; OpenCC Apache-2.0.\nconst SIMPLIFIED_ONLY_CHARACTERS='+json.dumps(chars,ensure_ascii=False)+';\n')
(ROOT/'data/script-preferences.json').write_text(json.dumps({'source':'https://github.com/BYVoid/OpenCC/blob/a806b775d038f9fa7c061f50d270115e7ad7da5b/data/dictionary/STCharacters.txt','sourceSha256':hashlib.sha256(file.read_bytes()).hexdigest(),'method':'OpenCC simplified keys excluding every traditional target and all MOE 4808 characters','simplifiedOnlyCount':len(chars),'relativeWeight':0.1,'characters':chars},ensure_ascii=False,indent=2)+'\n')
print('Simplified-only sampling characters:',len(chars))
